mapper.select:
SELECT c.CHANGE_ID, c.CHANGE_NO, c.CHANGE_TYPE, c.ASSET_ID, c.CHANGE_AMOUNT, c.CHANGE_DATE,
       c.FROM_DEPT_ID, c.TO_DEPT_ID, c.REASON, c.STATUS, c.REMARK, c.TENANT_ID,
       c.CREATE_BY, c.CREATE_TIME, c.UPDATE_BY, c.UPDATE_TIME, c.IS_DELETED,
       a.ASSET_CODE AS assetCode,
       a.ASSET_NAME AS assetName,
       d1.ORGNAME AS fromDeptName,
       d2.ORGNAME AS toDeptName
FROM TBL_FIXED_ASSET_CHANGE c
LEFT JOIN TBL_FIXED_ASSET_CARD a ON c.ASSET_ID = a.ASSET_ID AND a.IS_DELETED = 0
LEFT JOIN TBL_ORGANIZATION d1 ON c.FROM_DEPT_ID = d1.ORGID AND (d1.STATUS IS NULL OR d1.STATUS = 0)
LEFT JOIN TBL_ORGANIZATION d2 ON c.TO_DEPT_ID = d2.ORGID AND (d2.STATUS IS NULL OR d2.STATUS = 0)
WHERE c.IS_DELETED = 0

    AND c.TENANT_ID = #{param.tenantId}


    AND c.CHANGE_NO LIKE '%' || #{param.changeNo} || '%'


    AND c.CHANGE_TYPE = #{param.changeType}


    AND c.ASSET_ID = #{param.assetId}


    AND c.STATUS = #{param.status}


    AND c.CHANGE_DATE >= #{param.changeDateStart}


    AND c.CHANGE_DATE <= #{param.changeDateEnd}

ORDER BY c.CHANGE_DATE DESC, c.CREATE_TIME DESC
